// h264/ring_words_dec.sv -- the HPS interface's status words whose sources are on clk_dec (generated by tools/ring_layout.py -- edit the tables there, never this file).
// A mux on the word index: combinational, the index quasi-static (h264/ring_stat.sv holds
// it through the snapshot). Words of other domains read 0 here.

`default_nettype none

module ring_words_dec (
    input  wire  [5:0]  ix,
    input  wire  [31:0] f_fe_nal,            // w14: front end: NAL units
    input  wire  [31:0] f_fe_slice,          // w14: slices decoded
    input  wire  [31:0] f_fe_pic,            // w15: pictures (first_mb_in_slice 0)
    input  wire  [31:0] f_fe_refused,        // w15: refusals (REF_*)
    input  wire  [31:0] f_fe_err,            // w16: front-end errors (ERR_*)
    input  wire  [31:0] f_fe_bins,           // w16: CABAC bins / 256
    input  wire  [31:0] f_fe_pts_tag,        // w17: pictures tagged with a PTS
    input  wire  [31:0] f_fe_pts_drop,       // w17: PTS stamps dropped
    input  wire  [3:0] f_fe_refused_code,   // w18: the last refusal (h264_pkg REF_*)
    input  wire  [3:0] f_fe_err_code,       // w18: the last front-end error
    input  wire  [3:0] f_rc_err_code,       // w18: the last reconstruction error
    input  wire  [3:0] f_fe_pic_struct,     // w18: the last pic_struct
    input  wire  [4:0] f_rc_dpb_fill,       // w18: DPB stores in use
    input  wire  [0:0] f_out_ovf,           // w18: recon_out: a record pushed into a full FIFO (sticky)
    input  wire  [0:0] f_out_rel_bad,       // w18: recon_out: a release of a store not held (sticky)
    input  wire  [31:0] f_fe_sei_err,        // w18: malformed SEI NAL units
    input  wire  [31:0] f_rc_pic,            // w19: pictures reconstructed
    input  wire  [31:0] f_rc_mb,             // w19: macroblocks reconstructed
    input  wire  [31:0] f_rc_err,            // w20: reconstruction errors
    input  wire  [31:0] f_rc_ref_size,       // w20: pictures refused by size (> 3,600 MBs: word 81's cap_max_mbs; 0.1-0.10: > 1,620)
    input  wire  [31:0] f_rc_out_dropped,    // w21: stores dropped without output (no_output_of_prior_pics)
    input  wire  [31:0] f_rc_out_direct,     // w21: non-reference pictures output directly
    input  wire  [31:0] f_rc_out_over,       // w22: a DPB full of references (non-conforming)
    input  wire  [31:0] f_rc_stall,          // w22: reconstruction stall cycles
    input  wire  [31:0] f_rc_nrf_late,       // w23: an output below the last POC output (non-conforming max_num_reorder_frames)
    input  wire  [31:0] f_out_emit,          // w23: stores emitted to the display
    input  wire  [31:0] f_out_rel,           // w24: stores released by the display
    input  wire  [31:0] f_fe_pt_missing,     // w24: pictures missing a required picture timing SEI
    output logic [63:0] w
);
    always_comb begin
        w = 64'd0;
        case (ix)
            6'd14: begin w[31:0] = f_fe_nal; w[63:32] = f_fe_slice; end
            6'd15: begin w[31:0] = f_fe_pic; w[63:32] = f_fe_refused; end
            6'd16: begin w[31:0] = f_fe_err; w[63:32] = f_fe_bins; end
            6'd17: begin w[31:0] = f_fe_pts_tag; w[63:32] = f_fe_pts_drop; end
            6'd18: begin w[3:0] = f_fe_refused_code; w[7:4] = f_fe_err_code; w[11:8] = f_rc_err_code; w[15:12] = f_fe_pic_struct; w[20:16] = f_rc_dpb_fill; w[24:24] = f_out_ovf; w[25:25] = f_out_rel_bad; w[63:32] = f_fe_sei_err; end
            6'd19: begin w[31:0] = f_rc_pic; w[63:32] = f_rc_mb; end
            6'd20: begin w[31:0] = f_rc_err; w[63:32] = f_rc_ref_size; end
            6'd21: begin w[31:0] = f_rc_out_dropped; w[63:32] = f_rc_out_direct; end
            6'd22: begin w[31:0] = f_rc_out_over; w[63:32] = f_rc_stall; end
            6'd23: begin w[31:0] = f_rc_nrf_late; w[63:32] = f_out_emit; end
            6'd24: begin w[31:0] = f_out_rel; w[63:32] = f_fe_pt_missing; end
            default: ;
        endcase
    end
endmodule

`default_nettype wire
